type InputTask = {
  id?: unknown;
  duration?: unknown;
  dependsOn?: unknown;
};

type Task = {
  id: string;
  duration: number;
  dependsOn: string[];
};

export type Plan = {
  order: string[];
  layers: string[][];
  earliest: Record<string, { start: number; finish: number }>;
  totalDuration: number;
  criticalPath: string[];
};

function compareStrings(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function compareSequences(left: string[], right: string[]): number {
  const length = Math.min(left.length, right.length);
  for (let index = 0; index < length; index += 1) {
    const comparison = compareStrings(left[index], right[index]);
    if (comparison !== 0) return comparison;
  }
  return left.length - right.length;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function validateInput(value: unknown): Task[] {
  if (!isRecord(value) || !Array.isArray(value.tasks)) {
    throw new Error("Invalid input: 'tasks' must be an array");
  }

  const tasks: Task[] = [];
  const ids = new Set<string>();

  for (let index = 0; index < value.tasks.length; index += 1) {
    const raw = value.tasks[index];
    if (!isRecord(raw)) {
      throw new Error(`Invalid task at index ${index}: expected an object`);
    }
    const task = raw as InputTask;
    if (typeof task.id !== "string" || task.id.length === 0) {
      throw new Error(`Invalid task at index ${index}: 'id' must be a non-empty string`);
    }
    if (ids.has(task.id)) {
      throw new Error(`Invalid input: duplicate task id '${task.id}'`);
    }
    if (typeof task.duration !== "number" || !Number.isFinite(task.duration) || task.duration < 0) {
      throw new Error(`Invalid task '${task.id}': 'duration' must be a finite non-negative number`);
    }

    const dependencies = task.dependsOn === undefined ? [] : task.dependsOn;
    if (!Array.isArray(dependencies) || !dependencies.every((dependency) => typeof dependency === "string")) {
      throw new Error(`Invalid task '${task.id}': 'dependsOn' must be an array of strings`);
    }
    const dependencySet = new Set(dependencies);
    if (dependencySet.size !== dependencies.length) {
      throw new Error(`Invalid task '${task.id}': 'dependsOn' must not contain duplicates`);
    }
    if (dependencySet.has(task.id)) {
      throw new Error(`Invalid task '${task.id}': 'dependsOn' cannot contain the task itself`);
    }

    ids.add(task.id);
    tasks.push({ id: task.id, duration: task.duration, dependsOn: [...dependencies] });
  }

  for (const task of tasks) {
    for (const dependency of task.dependsOn) {
      if (!ids.has(dependency)) {
        throw new Error(`Invalid task '${task.id}': unknown dependency '${dependency}'`);
      }
    }
  }
  return tasks;
}

function findCycle(tasks: Task[], byId: Map<string, Task>): string[] | undefined {
  const state = new Map<string, 0 | 1 | 2>();
  const stack: string[] = [];

  const visit = (id: string): string[] | undefined => {
    state.set(id, 1);
    stack.push(id);
    for (const dependency of [...byId.get(id)!.dependsOn].sort(compareStrings)) {
      if (state.get(dependency) === 1) {
        return [...stack.slice(stack.indexOf(dependency)), dependency];
      }
      if (state.get(dependency) !== 2) {
        const cycle = visit(dependency);
        if (cycle) return cycle;
      }
    }
    stack.pop();
    state.set(id, 2);
    return undefined;
  };

  for (const task of [...tasks].sort((left, right) => compareStrings(left.id, right.id))) {
    if (state.get(task.id) === undefined) {
      const cycle = visit(task.id);
      if (cycle) return cycle;
    }
  }
  return undefined;
}

export function createPlan(input: unknown): Plan {
  const tasks = validateInput(input);
  const byId = new Map(tasks.map((task) => [task.id, task]));
  const cycle = findCycle(tasks, byId);
  if (cycle) throw new Error(`Cycle detected: ${cycle.join(" -> ")}`);

  const dependents = new Map<string, string[]>();
  const remainingDependencies = new Map<string, number>();
  for (const task of tasks) {
    dependents.set(task.id, []);
    remainingDependencies.set(task.id, task.dependsOn.length);
  }
  for (const task of tasks) {
    for (const dependency of task.dependsOn) dependents.get(dependency)!.push(task.id);
  }
  for (const list of dependents.values()) list.sort(compareStrings);

  const ready = tasks.filter((task) => task.dependsOn.length === 0).map((task) => task.id).sort(compareStrings);
  const order: string[] = [];
  while (ready.length > 0) {
    const id = ready.shift()!;
    order.push(id);
    for (const dependent of dependents.get(id)!) {
      const remaining = remainingDependencies.get(dependent)! - 1;
      remainingDependencies.set(dependent, remaining);
      if (remaining === 0) {
        ready.push(dependent);
        ready.sort(compareStrings);
      }
    }
  }

  const earliest: Plan["earliest"] = {};
  const pathById = new Map<string, string[]>();
  const layerById = new Map<string, number>();
  const layers: string[][] = [];
  for (const id of order) {
    const task = byId.get(id)!;
    let start = 0;
    let layer = 0;
    let predecessorPath: string[] = [];
    let hasPredecessor = false;
    for (const dependency of task.dependsOn) {
      const dependencyFinish = earliest[dependency].finish;
      if (!hasPredecessor || dependencyFinish > start || (dependencyFinish === start && compareSequences(pathById.get(dependency)!, predecessorPath) < 0)) {
        start = dependencyFinish;
        predecessorPath = pathById.get(dependency)!;
        hasPredecessor = true;
      }
      layer = Math.max(layer, layerById.get(dependency)! + 1);
    }
    earliest[id] = { start, finish: start + task.duration };
    pathById.set(id, [...predecessorPath, id]);
    layerById.set(id, layer);
    (layers[layer] ??= []).push(id);
  }
  for (const layer of layers) layer.sort(compareStrings);

  let totalDuration = 0;
  let criticalPath: string[] = [];
  let hasCriticalPath = false;
  for (const id of order) {
    const finish = earliest[id].finish;
    const candidate = pathById.get(id)!;
    if (!hasCriticalPath || finish > totalDuration || (finish === totalDuration && compareSequences(candidate, criticalPath) < 0)) {
      totalDuration = finish;
      criticalPath = candidate;
      hasCriticalPath = true;
    }
  }
  return { order, layers, earliest, totalDuration, criticalPath };
}

async function main(): Promise<void> {
  const [command, inputPath, ...extra] = Bun.argv.slice(2);
  if (command !== "plan" || !inputPath || extra.length > 0 || inputPath.startsWith("-")) {
    throw new Error("Usage: bun run src/cli.ts plan INPUT.json");
  }

  let source: string;
  try {
    source = await Bun.file(inputPath).text();
  } catch (error) {
    throw new Error(`Could not read '${inputPath}': ${error instanceof Error ? error.message : String(error)}`);
  }
  let input: unknown;
  try {
    input = JSON.parse(source);
  } catch (error) {
    throw new Error(`Invalid JSON: ${error instanceof Error ? error.message : String(error)}`);
  }
  process.stdout.write(`${JSON.stringify(createPlan(input))}\n`);
}

if (import.meta.main) {
  main().catch((error: unknown) => {
    process.stderr.write(`Error: ${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 1;
  });
}
